arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *sername*) echo "x-access-token" ;;
  *assword*) printf '%s' "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/askpass.sh
cd /tmp/joey-branch && GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git push origin friend/joey 2>&1 | tail -5
